package main

import (
	"fmt"
	"strings"
)

func main() {
	var first, sec string
	fmt.Scan(&first, &sec)
	var n int
	fmt.Scan(&n)

	n = (n-1)%4 + 1

	all := "<^>v"
	start := strings.IndexByte(all, first[0])
	end := strings.IndexByte(all, sec[0])

	if start == end || start == (end+2)%4 || start == (end-2+4)%4 {
		fmt.Println("undefined")
	} else {
		cw := false
		ccw := false

		// Check CW: (start + n) % 4 == end
		if (start+n)%4 == end {
			cw = true
		}
		// Check CCW: (start - n) % 4 == end
		if (start-n+4*100)%4 == end {
			ccw = true
		}

		if cw && ccw {
			fmt.Println("undefined")
		} else if cw {
			fmt.Println("cw")
		} else if ccw {
			fmt.Println("ccw")
		} else {
			fmt.Println("undefined")
		}
	}
}

